_cache = {}

def factorial(n):
    if n in _cache:
        return _cache[n]
    if n <= 1:
        result = 1
    else:
        result = n * factorial(n - 1)
    _cache[n] = result
    return result

print(factorial(5))  # 120
print(factorial(5))  # 120 — instant, read from _cache this time

def two_sum(numbers, target):
    seen = {}
    for i, n in enumerate(numbers):
        complement = target - n
        if complement in seen:
            return [seen[complement], i]
        seen[n] = i
    return None

