def retry(func, attempts=3):
    last_error = None
    for attempt in range(attempts):
        try:
            return func()
        except Exception as e:
            last_error = e
            print(f"Attempt {attempt + 1} failed: {e}")
    raise last_error

counter = {"tries": 0}
def flaky():
    counter["tries"] += 1
    if counter["tries"] < 3:
        raise RuntimeError("not yet")
    return "success"

print(retry(flaky))  # succeeds on the 3rd attempt

